<?php use function App\Core\{csrf, e, url}; ?>
<div class="page-header"><div><span class="eyebrow">SEU ESPAÇO DE PRODUTIVIDADE</span><h1>Minhas tarefas<span class="accent">.</span></h1><p class="muted">Organize hoje. Conquiste amanhã.</p></div><a class="button button-primary" href="<?= url('tasks/create') ?>">＋ Nova tarefa</a></div>
<div class="stats"><div class="stat"><div class="stat-symbol purple">▦</div><div><span>Total de tarefas</span><strong><?= $total ?></strong></div></div><div class="stat"><div class="stat-symbol green">✓</div><div><span>Concluídas</span><strong><?= $done ?></strong></div></div><div class="stat"><div class="stat-symbol orange">◷</div><div><span>Em andamento</span><strong><?= $total - $done ?></strong></div></div></div>
<section class="panel tasks-panel"><div class="panel-head"><div><h2>Sua lista</h2><p class="muted">Cada tarefa concluída é um passo adiante.</p></div><span class="count-pill"><?= $total ?> <?= $total === 1 ? 'tarefa' : 'tarefas' ?></span></div>
<?php if ($total === 0): ?><div class="empty-state"><div class="empty-icon">✎</div><h3>Seu próximo passo começa aqui.</h3><p>Você ainda não tem tarefas. Que tal criar a primeira?</p><a class="button button-primary" href="<?= url('tasks/create') ?>">Adicionar primeira tarefa</a></div>
<?php else: ?><div class="tasks-list"><?php foreach ($tasks as $task): ?><article class="task-item <?= $task['status'] === 'concluida' ? 'completed' : '' ?>"><div class="task-marker"><?= $task['status'] === 'concluida' ? '✓' : '○' ?></div><div class="task-body"><h3><?= e($task['title']) ?></h3><?php if ($task['description'] !== ''): ?><p><?= e($task['description']) ?></p><?php endif; ?><div class="meta"><span class="priority priority-<?= e($task['priority']) ?>"><?= ['baixa'=>'Baixa prioridade','media'=>'Média prioridade','alta'=>'Alta prioridade'][$task['priority']] ?></span><span><?= $task['status'] === 'concluida' ? 'Concluída' : 'Pendente' ?></span><?php if ($task['due_date']): ?><span>Prazo: <?= date('d/m/Y', strtotime($task['due_date'])) ?></span><?php endif; ?></div></div><div class="task-actions"><a class="button button-secondary button-small" href="<?= url('tasks/edit') ?>&amp;id=<?= (int)$task['id'] ?>">Editar</a><form method="post" action="<?= url('tasks/delete') ?>" onsubmit="return confirm('Deseja excluir esta tarefa?');"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$task['id'] ?>"><button type="submit" class="button button-danger button-small">Excluir</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
